import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

@DisplayName("80/76_path_sum")
class SolutionTest {

    @Test
    void shouldFindValidPathSum() {

        Completed solution = new Completed();

        TreeNode root = new TreeNode(
            5,
            new TreeNode(4, new TreeNode(11, new TreeNode(7), new TreeNode(2)), null),
            new TreeNode(8, new TreeNode(13), new TreeNode(4, null, new TreeNode(1)))
        );

        assertTrue(solution.hasPathSum(root, 22));
    }

    @Test
    void shouldRejectWhenNoPathMatches() {

        Completed solution = new Completed();

        TreeNode root = new TreeNode(1, new TreeNode(2), new TreeNode(3));

        assertFalse(solution.hasPathSum(root, 5));
    }

    @Test
    void shouldRejectEmptyTreeEvenForZero() {

        Completed solution = new Completed();

        assertFalse(solution.hasPathSum(null, 0));
    }

    @Test
    void shouldMatchSingleNodeEqualToTarget() {

        Completed solution = new Completed();

        assertTrue(solution.hasPathSum(new TreeNode(1), 1));
        assertFalse(solution.hasPathSum(new TreeNode(1), 0));
    }

    @Test
